set -e
export LANG=C LC_ALL=C
D=/opt/lzh/v7re/work/clkin
rm -rf $D; mkdir -p $D; cd $D
base64 -d << 'EOB64' > /tmp/clkin.zip

EOB64
unzip -oq /tmp/clkin.zip -d $D
ls *.tcl | sed 's/.tcl//' | xargs -P 6 -I{} sh -c '/opt/lzh/Xilinx/Vivado/2017.2/bin/vivado -mode batch -notrace -source {}.tcl > {}.log 2>&1; grep -q DONE_{} {}.log && echo OK {} || { echo FAIL {}; grep -m3 ERROR {}.log; }'
tar czf /tmp/clkin_out.tgz *.bit *.pips
echo CLKINDONE
